    CliSessionState mockSS = mock(CliSessionState.class);
    SessionStream mockOut = mock(SessionStream.class);
    mockSS.out = mockOut;
    cliDriver.processLocalCmd("use default;", proc, mockSS);
    return mockOut;
}

