    Optional<HivePrivilegeObject> hivePrivObject = outputHObjsCaptor.getValue().stream().filter(hpo -> hpo.getType().equals(HivePrivilegeObject.HivePrivilegeObjectType.STORAGEHANDLER_URI)).findAny();
