    properties.setProperty(KafkaTableProperties.HIVE_KAFKA_OPTIMISTIC_COMMIT.getName(), "false");
    Mockito.when(tableDesc.getProperties()).thenReturn(properties);
    Map<String, String> jobProperties = new HashMap<>();
