    Assert.assertEquals(String.valueOf(Integer.MAX_VALUE), producerProperties.get(ProducerConfig.RETRIES_CONFIG));
    Assert.assertEquals("true", producerProperties.get(ProducerConfig.ENABLE_IDEMPOTENCE_CONFIG));
}

