    // get a temporary directory
    assertEquals(mrTmpPath, spyContext.getTempDirForInterimJobPath(new Path("file:/user")));
    assertEquals(mrTmpPath, spyContext.getTempDirForInterimJobPath(new Path("file:///user")));
