    assertEquals(String.format("Expected query type for query '%s' is '%s', seen '%s'", query, expectedQueryType, queryType), expectedQueryType, queryType);
    String operationOrSqlKind = queryState.getSqlKind() == null ? queryState.getCommandType() : queryState.getSqlKind().toString();
    assertEquals(String.format("Expected operation(or sqlKind) for query '%s' is '%s', seen '%s'", query, expectedOperation, operationOrSqlKind), expectedOperation, operationOrSqlKind);
