private void checkQueryType(String query, QueryProperties.QueryType expectedQueryType, String expectedOperation) throws Exception {
    SessionState.start(new SessionState(conf));
    Context ctx = new Context(conf);
    ASTNode astNode = ParseUtils.parse(query, ctx);
    QueryState queryState = new QueryState.Builder().withHiveConf(conf).build();
    HiveConf.setVar(conf, HiveConf.ConfVars.HIVE_QUERY_ID, "test_query_id");
    SessionState.get().addQueryState("test_query_id", queryState);
    // RewriteSemanticAnalyzer needs a txn manager that supportsAcid()
    HiveTxnManager txnManager = mock(DbTxnManager.class);
    when(txnManager.supportsAcid()).thenReturn(true);
    queryState.setTxnManager(txnManager);
    BaseSemanticAnalyzer analyzer = spy(SemanticAnalyzerFactory.get(queryState, astNode));
    analyzer.initCtx(ctx);
    try {
        analyzer.analyze(astNode, ctx);
    } catch (SemanticException e) {
        LOG.info("Ignoring semantic exception because the inner state of the Semantic Analyzer still can and will be " + "asserted in this unit test.", e);
    } finally {
        // this is called by Compiler in production
        analyzer.endAnalysis(astNode);
    }
    QueryType queryType = analyzer.getQueryProperties().getQueryType();
    assertEquals(String.format("Expected query type for query '%s' is '%s', seen '%s'", query, expectedQueryType, queryType), expectedQueryType, queryType);
    String operationOrSqlKind = queryState.getSqlKind() == null ? queryState.getCommandType() : queryState.getSqlKind().toString();
    assertEquals(String.format("Expected operation(or sqlKind) for query '%s' is '%s', seen '%s'", query, expectedOperation, operationOrSqlKind), expectedOperation, operationOrSqlKind);
}

