    reset(mockedAuthorizer);
    runCmd("insert overwrite table part partition(position=2,DEPT,SAL)" + " select 2,2,2,2" + " union all" + " select 1,2,3,4" + " union all" + " select 3,4,5,6");
    Pair<List<HivePrivilegeObject>, List<HivePrivilegeObject>> io = getHivePrivilegeObjectInputs();
