    verify(wh, never()).getFileStatusesForLocation(part.getSd().getLocation());
    //Set STATS_AUTO_GATHER = true and set tbl as a VIRTUAL_VIEW
    MetastoreConf.setBoolVar(conf, ConfVars.STATS_AUTO_GATHER, true);
