    MetaStoreServerUtils.updateTableStatsForCreateTable(wh, db, tbl, null, MetastoreConf.newMetastoreConf(), new Path("/tmp/0"), false);
    assertTrue(messageWasLogged(MessageFormat.format(STATS_CALC_CALL_LOG_MSG_FORMAT, tbl.getCatName(), tbl.getDbName(), tbl.getTableName())));
    // DO_NOT_UPDATE_STATS in env context is set to false => invoke stats calculation
    EnvironmentContext env = new EnvironmentContext();
    env.putToProperties(StatsSetupConst.DO_NOT_UPDATE_STATS, StatsSetupConst.FALSE);
    MetaStoreServerUtils.updateTableStatsForCreateTable(wh, db, tbl, env, MetastoreConf.newMetastoreConf(), new Path("/tmp/0"), false);
    assertTrue(messageWasLogged(MessageFormat.format(STATS_CALC_CALL_LOG_MSG_FORMAT, tbl.getCatName(), tbl.getDbName(), tbl.getTableName())));
}
